ruleToc.chapterList:
@js:
var chaplist = new Array();
org.jsoup.Jsoup.parse(result).select("#chapter-list-1").toArray().forEach((vol,i)=>{
  chaplist.push({
    _id: String.fromCharCode("A".charCodeAt()+i),
    _name: vol.select("h3").text().replace("列表","").replace("章节","单话")
  });
  vol.select("ul a[href$=html]").toArray().reverse().forEach(a=>{
    chaplist.push(a);
  });
});
